BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.plan(15);
INSERT INTO auth.users(id,aud,role,email) VALUES ('de000000-0000-4000-8000-000000000001','authenticated','authenticated','reminder@local.test');
INSERT INTO public.organizations(id,name,username,type,join_code) VALUES ('de100000-0000-4000-8000-000000000001','Reminder fixture','reminder-fixture','school','976901');
INSERT INTO public.organization_members(organization_id,user_id,role,status) VALUES ('de100000-0000-4000-8000-000000000001','de000000-0000-4000-8000-000000000001','member','active');
INSERT INTO plugin_data.csf_terms(id,organization_id,code,label,school_year,semester,is_current,lifecycle_status) VALUES ('de200000-0000-4000-8000-000000000001','de100000-0000-4000-8000-000000000001','F26','Fall fixture','2026-2027','fall',true,'open');
INSERT INTO plugin_data.csf_term_deadlines(organization_id,term_id,deadline_type,title,due_at,audience)
SELECT 'de100000-0000-4000-8000-000000000001','de200000-0000-4000-8000-000000000001','application_close',audience,now()+interval '1 day',audience FROM unnest(ARRAY['all','officers','members','applicants']) AS audience;
INSERT INTO plugin_data.csf_meetings(id,organization_id,term_id,meeting_key,label) VALUES ('de300000-0000-4000-8000-000000000001','de100000-0000-4000-8000-000000000001','de200000-0000-4000-8000-000000000001','fixture','Fixture meeting');
INSERT INTO plugin_data.csf_meeting_sessions(organization_id,meeting_id,session_date,location) VALUES ('de100000-0000-4000-8000-000000000001','de300000-0000-4000-8000-000000000001',current_date+1,'Fixture gym');
CREATE TEMP TABLE reminder_result AS SELECT plugin_data.csf_member_home_context_snapshot('de100000-0000-4000-8000-000000000001','de000000-0000-4000-8000-000000000001',now(),now()+interval '7 days',current_date) AS data;
SELECT extensions.is((SELECT jsonb_array_length(data->'deadlines') FROM reminder_result),1,'unlinked member receives only all-audience deadline');
SELECT extensions.is((SELECT data #>> '{deadlines,0,title}' FROM reminder_result),'all','officer and member-only deadlines stay private');
SELECT extensions.is((SELECT data #>> '{meetingSessions,0,meeting_label}' FROM reminder_result),'Fixture meeting · Fixture gym','agenda label includes location');
SELECT extensions.is((SELECT jsonb_array_length(data->'meetingSessions') FROM reminder_result),1,'unlinked member receives meeting reminder');
SELECT extensions.is((SELECT data #>> '{meetingSessions,0,location}' FROM reminder_result),'Fixture gym','meeting location exposed');
SELECT extensions.is((SELECT data->'activities' FROM reminder_result),'[]'::jsonb,'no activity access granted');
SELECT extensions.is((SELECT data->'classmateCount' FROM reminder_result),'null'::jsonb,'no classmate count exposed');
SELECT extensions.ok(NOT EXISTS(SELECT 1 FROM reminder_result,jsonb_object_keys(data->'meetingSessions'->0) AS key WHERE key NOT IN ('id','session_date','starts_at','meeting_label','location')),'only scheduling fields exposed');
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_member_home_context_snapshot('de100000-0000-4000-8000-000000000002','de000000-0000-4000-8000-000000000001',now(),now()+interval '7 days',current_date)$q$,'42501','CSF member dashboard access denied.','cross organization denied');
INSERT INTO plugin_data.csf_profiles(id,organization_id,first_name,last_name,normalized_first_name,normalized_last_name) VALUES ('de400000-0000-4000-8000-000000000001','de100000-0000-4000-8000-000000000001','Pending','Fixture','pending','fixture');
INSERT INTO plugin_data.csf_profile_accounts(organization_id,profile_id,user_id,status,is_primary) VALUES ('de100000-0000-4000-8000-000000000001','de400000-0000-4000-8000-000000000001','de000000-0000-4000-8000-000000000001','pending',true);
SELECT extensions.is(jsonb_array_length(plugin_data.csf_member_home_context_snapshot('de100000-0000-4000-8000-000000000001','de000000-0000-4000-8000-000000000001',now(),now()+interval '7 days',current_date)->'deadlines'),1,'pending link retains all-audience reminder');
SELECT extensions.is(plugin_data.csf_member_home_context_snapshot('de100000-0000-4000-8000-000000000001','de000000-0000-4000-8000-000000000001',now(),now()+interval '7 days',current_date)->'viewer','null'::jsonb,'pending profile identity stays hidden');
UPDATE plugin_data.csf_term_deadlines SET status='cancelled' WHERE organization_id='de100000-0000-4000-8000-000000000001';
UPDATE plugin_data.csf_meeting_sessions SET status='cancelled' WHERE organization_id='de100000-0000-4000-8000-000000000001';
SELECT extensions.is(plugin_data.csf_member_home_context_snapshot('de100000-0000-4000-8000-000000000001','de000000-0000-4000-8000-000000000001',now(),now()+interval '7 days',current_date)->'deadlines','[]'::jsonb,'cancelled deadlines hidden');
SELECT extensions.is(plugin_data.csf_member_home_context_snapshot('de100000-0000-4000-8000-000000000001','de000000-0000-4000-8000-000000000001',now(),now()+interval '7 days',current_date)->'meetingSessions','[]'::jsonb,'cancelled meetings hidden');
SELECT extensions.ok(NOT has_function_privilege('authenticated','plugin_data.csf_member_home_context_snapshot(uuid,uuid,timestamptz,timestamptz,date)','EXECUTE'),'browser cannot invoke trusted actor RPC');
SELECT extensions.ok(has_function_privilege('service_role','plugin_data.csf_member_home_context_snapshot(uuid,uuid,timestamptz,timestamptz,date)','EXECUTE'),'server access retained');
SELECT * FROM extensions.finish();
ROLLBACK;
